{
  "meta": {
    "name": "Online Learning Platform",
    "description": "An online learning platform where instructors publish courses and students enroll, complete lessons, and provide reviews, with a freemium model offering access to paid courses and certificates via a premium subscription.",
    "version": "1.0.0",
    "theme": {
      "primaryColor": "blue",
      "fontSize": "large"
    }
  },
  "entities": [
    {
      "name": "Course",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true,
          "unique": false
        },
        {
          "name": "description",
          "type": "text",
          "required": false,
          "unique": false
        },
        {
          "name": "price",
          "type": "number",
          "required": false,
          "unique": false,
          "default": 0
        },
        {
          "name": "isFree",
          "type": "boolean",
          "required": false,
          "unique": false,
          "default": false
        }
      ],
      "relations": [
        {
          "name": "lessons",
          "kind": "oneToMany",
          "target": "Lesson",
          "required": false
        },
        {
          "name": "reviews",
          "kind": "oneToMany",
          "target": "Review",
          "required": false
        }
      ],
      "ownable": true
    },
    {
      "name": "Lesson",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true,
          "unique": false
        },
        {
          "name": "videoUrl",
          "type": "url",
          "required": true,
          "unique": false
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ],
      "ownable": false
    },
    {
      "name": "Enrollment",
      "fields": [
        {
          "name": "enrollmentDate",
          "type": "datetime",
          "required": true,
          "unique": false
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ],
      "ownable": true
    },
    {
      "name": "LessonCompletion",
      "fields": [
        {
          "name": "completionDate",
          "type": "datetime",
          "required": true,
          "unique": false
        }
      ],
      "relations": [
        {
          "name": "lesson",
          "kind": "manyToOne",
          "target": "Lesson",
          "required": true
        }
      ],
      "ownable": true
    },
    {
      "name": "Review",
      "fields": [
        {
          "name": "rating",
          "type": "integer",
          "required": true,
          "unique": false
        },
        {
          "name": "comment",
          "type": "text",
          "required": false,
          "unique": false
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ],
      "ownable": true
    }
  ],
  "roles": [
    {
      "name": "instructor",
      "description": "Can create and manage courses.",
      "isDefault": false
    },
    {
      "name": "student",
      "description": "Can enroll in courses, mark lessons complete, and review courses.",
      "isDefault": true
    },
    {
      "name": "premiumSubscriber",
      "description": "Has access to paid courses and certificates.",
      "isDefault": false
    }
  ],
  "permissions": [
    {
      "role": "instructor",
      "entity": "Course",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "instructor",
      "entity": "Lesson",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "Enrollment",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "LessonCompletion",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "student",
      "entity": "Course",
      "actions": [
        "read"
      ],
      "scope": "all",
      "requiresPlan": "free"
    },
    {
      "role": "student",
      "entity": "Enrollment",
      "actions": [
        "create",
        "read",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "LessonCompletion",
      "actions": [
        "create",
        "read"
      ],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "Review",
      "actions": [
        "create",
        "read"
      ],
      "scope": "own"
    },
    {
      "role": "premiumSubscriber",
      "entity": "Course",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "premiumSubscriber",
      "entity": "Enrollment",
      "actions": [
        "create",
        "read",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "premiumSubscriber",
      "entity": "LessonCompletion",
      "actions": [
        "create",
        "read"
      ],
      "scope": "own"
    },
    {
      "role": "premiumSubscriber",
      "entity": "Review",
      "actions": [
        "create",
        "read"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "Courses",
      "route": "/courses",
      "type": "list",
      "entity": "Course",
      "access": [
        "instructor",
        "student",
        "premiumSubscriber"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Course Detail",
      "route": "/courses/:id",
      "type": "detail",
      "entity": "Course",
      "access": [
        "instructor",
        "student",
        "premiumSubscriber"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "New Course",
      "route": "/courses/new",
      "type": "form",
      "entity": "Course",
      "access": [
        "instructor"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Edit Course",
      "route": "/courses/:id/edit",
      "type": "form",
      "entity": "Course",
      "access": [
        "instructor"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Lessons",
      "route": "/courses/:courseId/lessons",
      "type": "list",
      "entity": "Lesson",
      "access": [
        "instructor",
        "student",
        "premiumSubscriber"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "New Lesson",
      "route": "/courses/:courseId/lessons/new",
      "type": "form",
      "entity": "Lesson",
      "access": [
        "instructor"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Edit Lesson",
      "route": "/courses/:courseId/lessons/:id/edit",
      "type": "form",
      "entity": "Lesson",
      "access": [
        "instructor"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Instructor Dashboard",
      "route": "/dashboard",
      "type": "dashboard",
      "access": [
        "instructor"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Students Enrolled",
          "entity": "Enrollment",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Lessons Completed",
          "entity": "LessonCompletion",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Student Dashboard",
      "route": "/student-dashboard",
      "type": "dashboard",
      "access": [
        "student",
        "premiumSubscriber"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "table",
          "label": "My Enrollments",
          "entity": "Enrollment"
        },
        {
          "type": "table",
          "label": "My Lesson Completions",
          "entity": "LessonCompletion"
        }
      ]
    },
    {
      "name": "Certificate",
      "route": "/certificate/:courseId",
      "type": "custom",
      "access": [
        "premiumSubscriber"
      ],
      "fields": [],
      "widgets": [],
      "requiresPlan": "premium"
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumAccessGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Certificate"
        ],
        "entities": [],
        "features": [
          "access_paid_courses",
          "certificates"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "courseOwnership",
      "entity": "Course"
    },
    {
      "type": "ownership",
      "id": "enrollmentOwnership",
      "entity": "Enrollment"
    },
    {
      "type": "ownership",
      "id": "lessonCompletionOwnership",
      "entity": "LessonCompletion"
    },
    {
      "type": "ownership",
      "id": "reviewOwnership",
      "entity": "Review"
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "currency": "usd",
      "interval": "month",
      "isDefault": true,
      "features": [
        "access_free_courses"
      ]
    },
    {
      "name": "premium",
      "price": 10,
      "currency": "usd",
      "interval": "month",
      "isDefault": false,
      "features": [
        "access_paid_courses",
        "certificates"
      ]
    }
  ],
  "auth": {
    "strategy": "email_password",
    "providers": [],
    "requireAuth": true
  },
  "assumptions": [
    "Users will have distinct roles of 'instructor' and 'student'.",
    "A 'premium subscription' implies a recurring payment model.",
    "Completion certificates are generated upon completion of all lessons in a paid course.",
    "Course ratings are numerical (e.g., 1-5 stars)."
  ]
}
